<?php
namespace qqworld_collector\module\collect_filter; use qqworld_collector\lib; class qqworld_collector_parse_baike_com_post_excerpt extends lib { var $post_content = array(); public function __construct() { add_filter( 'qqworld-collector-parse-baike-com-post-excerpt', array($this, 'filter'), 10, 6 ); } public function filter($item, $source_link, $html, $type, $item_args, $download_args) { $json = json_decode($item, true); if ($json) { $item = ''; foreach ($json as $it) { switch ($it['type']) { case 'paragraph': $item .= '<p>'; foreach ($it['content'] as $con) { switch ($con['type']) { case 'text': $item .= $con['text']; break; } } $item .= '</p>'; break; } } } return $item; } } new qqworld_collector_parse_baike_com_post_excerpt; ?>